"""Empirically locate the abscissa of convergence of the prime zeta function
P(s) = sum_p p^{-s} (Theorem primeZeta_summable_iff): the wall sits at s = 1."""
from __future__ import annotations
from math import log
from typing import List

def primes_up_to(limit: int) -> List[int]:
    if limit < 2:
        return []
    sieve = [True] * (limit + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(limit ** 0.5) + 1):
        if sieve[i]:
            for j in range(i * i, limit + 1, i):
                sieve[j] = False
    return [i for i, p in enumerate(sieve) if p]

def prime_zeta_partial(s: float, primes: List[int]) -> float:
    return sum(p ** (-s) for p in primes)

def main() -> None:
    primes = primes_up_to(200_000)
    half = primes[: len(primes) // 2]
    print(f"{'s':>7} | {'S_N(s)':>16} | {'S_N/S_(N/2)':>12} | verdict")
    for s in (3.0, 2.0, 1.5, 1.1, 1.0, 0.5, 0.0, -1.0):
        full = prime_zeta_partial(s, primes)
        low = prime_zeta_partial(s, half)
        ratio = full / low if low else float("inf")
        verdict = "converges" if s > 1 else "DIVERGES"
        print(f"{s:>7.2f} | {full:>16.6f} | {ratio:>12.6f} | {verdict}  (s {'>' if s>1 else '<='} 1)")

if __name__ == "__main__":
    main()

"""Exhibit the dichotomy (prime_zeta_boundary_vs_zeta_regularization):
the bare prime series diverges at s = -1 (sum of all primes), while the full zeta
function escapes to zeta(-1) = -1/12 (riemannZeta_neg_one_eq) by analytic
continuation through exact Bernoulli numbers."""
from __future__ import annotations
from fractions import Fraction
from math import comb
from typing import List

def primes_up_to(limit: int) -> List[int]:
    sieve = [True] * (limit + 1)
    sieve[0] = sieve[1] = False
    for i in range(2, int(limit ** 0.5) + 1):
        if sieve[i]:
            for j in range(i * i, limit + 1, i):
                sieve[j] = False
    return [i for i, p in enumerate(sieve) if p]

def bernoulli(n: int) -> List[Fraction]:
    b: List[Fraction] = []
    for m in range(n + 1):
        s = sum(Fraction(comb(m + 1, k)) * b[k] for k in range(m))
        b.append(Fraction(1) if m == 0 else -s / Fraction(m + 1))
    return b

def zeta_neg(n: int) -> Fraction:
    return -bernoulli(n + 1)[n + 1] / Fraction(n + 1)

def main() -> None:
    print("Bare prime series at s = -1  (sum of all primes up to N):")
    for N in (100, 10_000, 1_000_000):
        print(f"  primes <= {N:>9}:  sum p = {sum(primes_up_to(N)):>14}  (growing -> diverges)")
    z = zeta_neg(1)
    print(f"\nAnalytic continuation of the FULL zeta: zeta(-1) = {z}")
    assert z == Fraction(-1, 12)
    print("The integer series escapes to -1/12; the prime series cannot (natural boundary).")

if __name__ == "__main__":
    main()

